<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://&lt;your Octryx AI host&gt;/api/v1/mcp/knowledge-protocol/mcp&quot;</span></span>
